def try_solve_cycles(n, k, graph):
    """Try to find k cycles where each has length >= 3, not divisible by 3,
    and each has a unique representative vertex."""

    cycles = []
    representatives = []
    used_nodes = set()
    all_used = [False] * (n + 1)

    # Try from different starting vertices
    candidates = list(range(1, n + 1))
    random.shuffle(candidates)

    for start in candidates:
        if all_used[start] or len(cycles) >= k:
            continue

        # Find a cycle passing through 'start'
        cycle_found = []
        assigned_rep = None

        # Use iterative DFS to find a cycle
        stack = []
        current_path = [start]
        in_current_path = {start}

        while stack or (len(cycle_found) == 0):
            if len(current_path) >= 2:
                neighbors = graph[current_path[-1]]
                next_node = None

                # Check if we can close a cycle
                for i, nb in enumerate(neighbors):
                    if i == len(neighbors) - 1:  # Last neighbor of current node
                        if nb == current_path[0] and len(current_path) >= 3:
                            cycle_found = current_path
                            assigned_rep = start
                            break
                    elif nb not in in_current_path:
                        next_node = nb
                        break

                if next_node is None and cycle_found:
                    break

                if next_node is None:
                    # Backtrack
                    break

                next_node = next_node if next_node else neighbors[-1]
                if is_valid_next(next_node, in_current_path):
                    in_current_path.add(next_node)
                    current_path.append(next_node)
                    stack.append((next_node, len(current_path)))
            else:
                if len(cycle_found) == 0:
                    break

        if cycle_found and assigned_rep and assigned_rep not in used_nodes:
            cycle_len = len(cycle_found)
            if cycle_len >= 3 and cycle_len % 3 != 0:
                cycles.append(cycle_found)
                representatives.append(assigned_rep)
                for node in cycle_found:
                    all_used[node] = True
                used_nodes.add(assigned_rep)

    # Output result
    if len(cycles) >= k:
        result = ["CYCLES"]
        for c in cycles[:k]:
            result.append(str(len(c)))
            result.append(' '.join(map(str, c)))
        return '\n'.join(result)

    return "-1"

def is_valid_next(nb, visited):
    return nb not in visited

def try_solve_path(n, m, k, graph):
    """Try to find a simple path with length >= n/k."""
    required_length = (n + k - 1) // k if k <= n else 1

    # Use DFS to find longest path
    for start in range(1, n + 1):
        # Simple DFS for longest path
        path_len, found_path = dfs_longest_path(start, graph, required_length)
        if path_len >= required_length:
            return create_path_output(found_path, 'PATH')

    return "-1"

def dfs_longest_path(start, graph, required_length):
    """Find longest simple path from start."""
    best_path = []

    def dfs(current, path, visited):
        nonlocal best_path

        if len(path) > len(best_path):
            best_path = path[:]

        if len(path) >= required_length:
            return

        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                dfs(neighbor, path, visited)
                path.pop()
                visited.remove(neighbor)

    visited = {start}
    dfs(start, [start], visited)

    if len(best_path) >= required_length:
        return len(best_path), best_path

    return len(best_path), []

def create_path_output(path, first_line_action):
    result = [first_line_action]
    result.append(str(len(path)))
    result.append(' '.join(map(str, path)))
    return '\n'.join(result)

