    # prefix[i][0][k] = 0 (for prefix 1D)
    # Using prefix[i][j+1] for column j

    # prefix_table[i][col] = list of 26 character counts for row i, columns 0 to col-1
    prefix_table = [[[0]*26 for _ in range(m+1)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            # Copy previous counts
            prefix_table[i][j+1] = prefix_table[i][j][:]
            char_idx = ord(matrix[i][j]) - ord('a')
            prefix_table[i][j+1][char_idx] += 1

    def get_chars(row, c1, c2):
        """Get character counts for matrix[row][c1..c2] inclusive (0-indexed)"""
        if c1 > c2 or c2 >= m:
            return [0] * 26
        return [prefix_table[row][c2+1][k] - prefix_table[row][c1][k] for k in range(26)]

    def row_can_be_palindrome(r, c1, c2):
        """Check if row r[c1..c2] can be rearranged into a palindrome"""
        counts = get_chars(r, c1, c2)
        odd_count = sum(1 for c in counts if c % 2 == 1)
        return odd_count <= 1

    # Also need prefix sums across rows for column checks
    # row_prefix[i][j][k] = count of character k in column range [c1, c2] for rows 0..i
    # Actually, for column palindrome check, we need same character counts in symmetric rows

    count = 0

    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):

                    # Check if all rows can be palindromes
                    all_rows_ok = True
                    for r in range(r1, r2 + 1):
                        if not row_can_be_palindrome(r, c1, c2):
                            all_rows_ok = False
                            break
                    if not all_rows_ok:
                        continue

                    # Check if symmetric rows have same character counts
                    # Number of row pairs to check: (r2 - r1) // 2
                    half_height = (r2 - r1)

                    all_symmetric_ok = True
                    for r in range(half_height // 2):
