from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""
    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ""

    # Parse edges: (a-1, b-1, e, original_index)
    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a - 1, b - 1, e, i))

    # Kruskal's algorithm to build MST
    sorted_edges = sorted(edges, key=lambda x: x[2])

    parent = list(range(n))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        curr = x
        while parent[curr] != root:
            parent[curr], curr = root, parent[curr]
        return root

    mst_edges = []
    for u, v, w, i in sorted_edges:
        root_u, root_v = find(u), find(v)
        if root_u != root_v:
            parent[root_v] = root_u
            mst_edges.append((u, v, w, i))
            if len(mst_edges) == n - 1:
                break

    # Build adjacency list for MST with weights
    adj = [[] for _ in range(n)]
    for u, v, w, _ in mst_edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # BFS from node 0 for depth and parent
    depth = [-1] * n
    parent = list(range(n))

    queue = deque([0])
    depth[0] = 0

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if depth[v] == -1:
                depth[v] = depth[u] + 1
                parent[v] = u
                queue.append(v)

    # Binary lifting tables for LCA and path maximum
    LOG = 21
    up = [[-1] * n for _ in range(LOG)]
    mx = [[0] * n for _ in range(LOG)]

    for i in range(n):
        up[0][i] = parent[i]
        if i == 0:
            mx[0][i] = 0
        else:
            mx[0][i] = 0

    for i in range(1, LOG):
        for j in range(n):
            if up[i-1][j] != -1:
                up[i][j] = up[i-1][up[i-1][j]]
                x = up[i-1][j]
                if x != -1:
                    mx[i][j] = max(mx[i-1][j], mx[i-1][x])
                else:
                    mx[i][j] = mx[i-1][j]

    def query_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        result = 0
        diff = depth[u] - depth[v]

        for i in range(LOG):
            if diff & (1 << i):
                result = max(result, mx[i][u])
                u = up[i][u]

        if u == v:
            return result

        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
                result = max(result, mx[i][u], mx[i][v])
                u = up[i][u]
                v = up[i][v]

        result = max(result, mx[0][u], mx[0][v])
        return result

    # Process non-MST edges
    results = []
    mst_set = set()
    for u, v, _, _ in mst_edges:
        mst_set.add((u, v))
        mst_set.add((v, u))

    for u, v, w, i in edges:
        if (u, v) not in mst_set:
            results.append(str(query_max(u, v)))

    return '\n'.join(results)

