def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    if not lines or len(lines) < 2:
        return '\n0\n'

    try:
        n, k = map(int, lines[0].split())
        p = list(map(int, lines[1].split()))

        pairs = []
        for i in range(min(k, len(lines) - 2)):
            parts = lines[2 + i].split()
            if len(parts) >= 2:
                x, y = int(parts[0]), int(parts[1])
                if 1 <= x <= n and 1 <= y <= n and x != y:
                    pairs.append((x, y))
    except:
        return '\n0\n'

    # Build combined graph
    graph = collections.defaultdict(list)
    in_degree = [0] * (n + 1)

    # Add prerequisite edges: p_i is prerequisite for topic (i+1), so p_i -> (i+1)
    for i in range(n):
        prereq = p[i]
        topic = i + 1
        if prereq > 0 and prereq <= n:
            graph[prereq].append(topic)
            in_degree[topic] += 1

    # Add immediate_successor pairs
    for x, y in pairs:
        if 1 <= x <= n and 1 <= y <= n and x != y:
            # x must be immediately before y, so x -> y
            graph[x].append(y)
            in_degree[y] += 1

    # Kahn's algorithm for topological sort
    queue = collections.deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if valid ordering exists
    if len(result) == n:
        return '\n' + ' '.join(map(str, result)) + '\n'
    else:
