        while d * d <= x:
            while x % d == 0:
                factors[d] = factors.get(d, 0) + 1
                x //= d
            d += 1
        if x > 1:
            factors[x] = factors.get(x, 0) + 1
        prime_info[i] = factors

    # Get all unique primes
    all_primes = set()
    for factors in prime_info.values():
        all_primes.update(factors.keys())

    total_ops = 0

    # For each prime, solve a max flow problem
    for p in sorted(all_primes):
        # Find positions with this prime factor
        has_prime = {}
        even_positions = []
        odd_positions = []

        for i in range(n):
            if has_prime.get(i, 0) > 0:
                has_prime[i] = has_prime.get(i, 0) + 1

        for i in range(n):
            if p in prime_info[i]:
                has_prime[i] = prime_info[i][p]
            if i % 2 == 0 and has_prime[i] > 0:
                even_positions.append(i)
            elif i % 2 == 1 and has_prime[i] > 0:
                odd_positions.append(i)

        # Build bipartite graph for this prime
        # Only positions with this prime can participate
        # Source -> even positions (with prime) -> edges -> odd positions (with prime) -> Sink

        S = 2 * n
        T = 2 * n + 1

        # Source to even nodes
        even_cap = [0] * (2 * n + 2)
        for i in even_positions:
            even_cap[i] = has_prime[i]

        # Odd nodes to sink
        odd_cap = [0] * (2 * n + 2)
        for i in odd_positions:
            odd_cap[i] = has_prime[i]

        # Build flow network using capacity matrix
        cap = [[0] * (2 * n + 2) for _ in range(2 * n + 2)]
        adj = [[] for _ in range(2 * n + 2)]

        for i in even_positions:
            cap[S][i] = has_prime[i]
            adj[S].append(i)

        for i in odd_positions:
            cap[i][T] = has_prime[i]
            adj[i].append(T)

        for u, v in edges:
            if u in has_prime and v in has_prime:
                cap[u][v] = float('inf')
                cap[v][u] = 0  # Backward edge
                cap[u][u] = float('inf')

        # Dinic's algorithm for max flow
        level = [0] * (2 * n + 2)
        ptr = [0] * (2 * n + 2)

        max_flow = 0

        def bfs():
            nonlocal level
            level = [-1] * (2 * n + 2)
            level[S] = 0
            queue = deque([S])
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if cap[u][v] > 0 and level[v] == -1:
                        level[v] = level[u] + 1
                        queue.append(v)
            return level[T] != -1

        def dfs(u, pushed):
            nonlocal max_flow
            if pushed == 0 or u == T:
                return pushed

            for v in range(ptr[u], len(adj[u])):
                ptr[u] = v
                if level[v] != level[u] + 1 or cap[u][v] == 0:
                    continue
                tr = dfs(v, min(pushed, cap[u][v]))
                if tr == 0:
                    continue
                cap[u][v] -= tr
                cap[v][u] += tr
                return tr
            return 0

        while bfs():
            ptr = [0] * (2 * n + 2)
            pushed = dfs(S, float('inf'))
            while pushed:
                max_flow += pushed
                pushed = dfs(S, float('inf'))

        # Total operations for this prime equals the max flow on the bipartite graph
        max_ops = min(sum(has_prime[i] for i in even_positions), 
                      sum(has_prime[i] for i in odd_positions))
        total_ops += max_ops

    return str(total_ops) + '\n'

