        for col2 in range(m):
            new_A = apply_sort(table1, col2)
            if new_A == B:
                indices_part = f"{col1 + 1} {col2 + 1}"
                return f'\n2\n {indices_part}'

    # Try triples of column sorts
    for col1 in range(m):
        table1 = apply_sort(A, col1)
        for col2 in range(m):
            if col2 == col1: continue
            table2 = apply_sort(table1, col2)
            for col3 in range(m):
                if col3 == col1 or col3 == col2: continue
                new_A = apply_sort(table2, col3)
