import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    x1, y1, x2, y2 = map(float, lines[0].split())
    n = int(lines[1])
    circles = []
    for i in range(2, 2+n):
        xi, yi, ri = map(float, lines[i].split())
        circles.append((xi, yi, ri))

    mid_x = (x1 + x2) / 2
    mid_y = (y1 + y2) / 2
    dx = x2 - x1
    dy = y2 - y1
    seg_len_sq = dx*dx + dy*dy
    R = math.sqrt(seg_len_sq) / 2

    # Direction of perpendicular bisector
    if seg_len_sq == 0:
        px, py = 1.0, 0.0
    else:
        px = -dy / math.sqrt(seg_len_sq)
        py = dx / math.sqrt(seg_len_sq)

    def center(t):
        return (mid_x + t * px, mid_y + t * py)

    def new_radius(t):
        return math.sqrt(R*R + t*t)

    # For each t, check if any circle is intersected
    # Two circles intersect if: |r_new - r_c| < dist < r_new + r_c
    def has_intersection(t):
        cx, cy = center(t)
        r_new = new_radius(t)
        for ox, oy, r in circles:
            dist = math.sqrt((cx - ox)**2 + (cy - oy)**2)
            # Strict intersection (not allowed)
            if dist < r_new + r and dist > abs(r_new - r):
                return True
        return False

    # Binary search for optimal t
    lo, hi = -1e7, 1e7
    for _ in range(80):
        mid = (lo + hi) / 2
        if has_intersection(mid):
            lo = mid
        else:
            hi = mid

    return str(round(new_radius(hi), 10))


