def solution(input_str):
    input_lines = input_str.strip().split('\n')
    if not input_lines:
        return ''
    q = int(input_lines[0])
    queries = []
    for i in range(1, len(input_lines)):
        line = input_lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 2:
            r, n = int(parts[0]), int(parts[1])
            queries.append((r, n))

    max_r = 1000000
    max_n = 1000000
    max_e = 21  # 2^20 <= 10^6 < 2^21, so max exponent is 19

    # Precompute SPF (Smallest Prime Factor) for fast factorization
    spf = list(range(max_n + 1))
    for i in range(2, int(max_n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute f[r][e] using recurrence:
    # f[r][0] = 1 for all r (since f(1) = 1)
    # f[0][e] = 2 for e > 0 (since f0 counts coprime factorizations)
    # f[r][e] = f[r-1][e] + f[r][e-1] for r > 0, e > 0
    # This recurrence captures the behavior of the divisor sum recurrence on prime powers
    f = [[0] * (max_e + 1) for _ in range(max_r + 1)]
    f[0][0] = 1
    for e in range(1, max_e + 1):
        f[0][e] = 2

    for r in range(1, max_r + 1):
        f[r][0] = 1
        for e in range(1, max_e + 1):
            f[r][e] = (f[r-1][e] + f[r][e-1]) % MOD

    results = []
    for r, n in queries:
        if n == 1:
            results.append(1)
            continue

        temp = n
        ans = 1
        while temp > 1:
            p = spf[temp]
            e = 0
            while temp % p == 0:
                temp //= p
                e += 1
            # f[r][e] is the same for any prime p, just depends on r and exponent e
            ans = (ans * f[r][e]) % MOD
        results.append(ans)

    return '\n'.join(map(str, results))
